  39   static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
  40   static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
  41   static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
  42 
  43   static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
  44   static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
