  49   // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
  50   // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
  51   static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
  52   static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
  53   static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
  54   static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
  55 
  56   static constexpr unsigned kPollIterations = kDmiPollIterations;
