  60   void resume(const hybrid_state_v1& state)
  61   {
  62     if (state.magic != HYBRID_STATE_MAGIC)
  63       throw std::runtime_error("ResumeDriver::resume: bad magic");
  64     if (state.version != HYBRID_STATE_VERSION)
  65       throw std::runtime_error("ResumeDriver::resume: unsupported version");
