  70     // dmactive must transition 0->1 in its own write before any other
  71     // DMCONTROL bit is honored (RISC-V Debug Spec).
  72     bus_.write(kDmcontrol, kDmcontrolDmactive);
  73     request_halt();
  74     poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
