 138   // Abstract-first CSR write with Program Buffer fallback.
 139   // Tries an abstract register write; if the DM signals cmderr, clears it,
 140   // stages the value in scratch_gpr via abstract GPR write, then executes a
 141   // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
 142   // to x5 (t0) which the GPR restore loop overwrites later.
 143   void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
 144                                  uint8_t scratch_gpr = 5)
 145   {
 146     write_64bit_register(regno_csr(csr), value);
 147     if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
 148     bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
 149     write_64bit_register(regno_gpr(scratch_gpr), value);
 150     const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
 151     exec_progbuf(bus_, std::span<const uint32_t>{pb});
 152   }
