 154   // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
 155   // is rejected until the bits are W1C-cleared. We tolerate per-register
 156   // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
 157   // error before resuming so the hart isn't left in a stuck state.
 158   // B17: record the last observed non-zero cmderr and a clear count so a
 159   // partially-broken restore is observable via the public accessors
 160   // instead of silently swallowed.
 161   void clear_cmderr_if_set()
 162   {
 163     const auto status = bus_.read(kAbstractcs);
 164     const auto code = (status & kAbstractcsCmderrMask) >> 8;
 165     if (code != 0u) {
 166       last_observed_cmderr_ = code;
 167       ++cmderr_clear_count_;
 168       bus_.write(kAbstractcs, kAbstractcsCmderrMask);
 169     }
 170   }
 171 
 172   DmiBus& bus_;
 173   uint32_t last_observed_cmderr_ = 0;
 174   uint64_t cmderr_clear_count_   = 0;
 175 
 176 public:
 177   // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
 178   // at least one abstract write tripped a sticky cmderr the restore
 179   // tolerated by clearing. cmderr_clear_count() is the total number of
 180   // such clears across all calls into clear_cmderr_if_set() this run.
 181   auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
 182   auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
