 185 // Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
 186 // via an Abstract Command. Halts-and-reads contract: caller must have the
 187 // hart in the halted state. Shared with StateDrain (drain at exit). If
 188 // abstractcs.cmderr goes sticky after the command, the helper clears it and
 189 // reports nullopt rather than blocking the caller -- a missing CSR mirrors as
 190 // absent instead of corrupting the adjacent field.
 191 inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
 192                                      const char* poll_label
 193                                        = "read_register_64")
 194   -> std::optional<uint64_t>
 195 {
 196   using RD = ResumeDriver;
 197   bus.write(RD::kCommand,
 198             access_register_command(regno, AarSize::Bits64, /*write=*/false));
 199   poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
 200   const auto status = bus.read(RD::kAbstractcs);
 201   if ((status & RD::kAbstractcsCmderrMask) != 0u) {
 202     bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
 203     return std::nullopt;
 204   }
 205   const uint64_t lo = bus.read(RD::kData0);
 206   const uint64_t hi = bus.read(RD::kData1);
 207   return lo | (hi << 32);
 208 }
 209 
 210 inline auto read_register_64(DmiBus& bus, uint16_t regno,
 211                              const char* poll_label = "read_register_64")
 212   -> uint64_t
 213 {
 214   return read_register_64_checked(bus, regno, poll_label).value_or(0u);
 215 }
