213	 213       if (v_data_equal)
214	 214         baseline_skip_count_ += 32;
215	 215       else
216	 216         pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
217	 217 
218	 218       // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
219	 219       // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
220	 220       // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
221	 221       // x5/x6 are overwritten by the GPR loop below, so no leakage.
222	 222       // LG2 clobber rule: the data sweep's own vsetvl overwrote vtype/vl/
223	 223       // vstart, so baseline equality only proves this vsetvl redundant when
224	 224       // the sweep did NOT run.
225	 225       const bool vcfg_equal = v_data_equal && v_cfg_at_reset_
226	 226         && state.vl == baseline_.vl && state.vtype == baseline_.vtype;
227	 227       if (vcfg_equal) {
228	 228         ++baseline_skip_count_;  // the elided vsetvl exec
229	 229       } else {
230	 230         write_64bit_register(regno_gpr(5), state.vl);
231	 231         write_64bit_register(regno_gpr(6), state.vtype);
232	 232         const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
233	 233         exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
234	 234       }
235	 235       // vstart must come AFTER vsetvl: vsetvl resets vstart to 0 -- so its
236	 236       // baseline skip is likewise only valid when no vsetvl executed.
237	 237       if (!(vcfg_equal && baseline_skips(state.vstart, baseline_.vstart)))
238	 238         write_csr_abstract_or_pb(kCsrVstart, state.vstart);
239	 239       if (!baseline_skips(state.vxsat, baseline_.vxsat))
240	 240         write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
241	 241       if (!baseline_skips(state.vxrm, baseline_.vxrm))
242	 242         write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
243	 243       if (!baseline_skips(state.vcsr, baseline_.vcsr))
244	 244         write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
245	 245     }
246	 246 
247	 247     // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
248	 248     // S/U-mode handoff, read-modify-write the prv field so the ROI executes
249	 249     // in the drained privilege; M-mode states skip the write (prv already 3).
250	 250     // Before the GPR loop: a PB fallback would clobber scratch x5.
251	 251     if (state.priv != 3) {
252	 252       // L2 slice: with PMP implemented and no matching entry, every S/U
253	 253       // access faults (priv spec v1.10) -- mirror the producer's PMP block
254	 254       // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
255	 255       // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
256	 256       // RV64. Tolerant writes: entries beyond what the hart implements
257	 257       // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
258	 258       for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
259	 259         write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
260	 260       for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
261	 261         write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
262	 262 
263	 263       const uint64_t dcsr =
264	 264         read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
265	 265       write_csr_abstract_or_pb(kCsrDcsr,
266	 266                                (dcsr & ~uint64_t{0x3}) | state.priv);
267	 267       // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
268	 268       // silently measure the ROI in the wrong privilege. Verify and abort.
269	 269       const uint64_t got =
270	 270         read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
271	 271         & 0x3u;
272	 272       if (got != state.priv)
273	 273         throw std::runtime_error(
274	 274           "ResumeDriver::resume: engine does not implement privilege level "
275	 275           + std::to_string(state.priv)
276	 276           + " (dcsr.prv pinned to " + std::to_string(got)
277	 277           + "); pick an S/U-capable engine");
278	 278     }
279	 279 
280	 280     // Andes V5 + M-ext CSR restore (abstract-only, LG1-gated). See
281	 281     // restore_andes_m_ext.
282	 282     restore_andes_m_ext(state);
283	 283 
284	 284     // v5: L2C MMIO config restore. Runs BEFORE the GPR loop (like the V sweep):
285	 285     // it stages an address + value into scratch GPRs x5/x6 and the GPR loop
286	 286     // below overwrites them with their architectural values, so the clobber is
287	 287     // safe. It CANNOT run after the loop, where every GPR already holds its
288	 288     // final value. See restore_l2c.
289	 289     restore_l2c(state);
290	 290 
291	 291     // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite): one
292	 292     // abstract register write per GPR.
293	 293     for (uint16_t i = 1; i < 32; ++i)
294	 294       write_64bit_register(regno_gpr(i), state.gpr[i]);
295	 295     write_64bit_register(regno_csr(kCsrDpc), state.pc);
296	 296 
297	 297     write_csr_tolerant_gated(kCsrMtvec, state.mtvec, baseline_.mtvec);
298	 298 
299	 299     // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
300	 300     // register with no hardware side effects, legal to use inside a trap-free
301	 301     // ROI. Restore it so a value stashed before the handoff survives into the
302	 302     // vsim phase.
303	 303     write_csr_tolerant_gated(kCsrMscratch, state.mscratch, baseline_.mscratch);
304	 304 
305	 305     // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
306	 306     // interrupt-free ROI envelope these are ordinary read/write registers, so a
307	 307     // value stashed before the handoff must survive into the vsim phase (same
308	 308     // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
309	 309     // hardware-driven pending bits, or mtval on a core that hardwires it)
310	 310     // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
311	 311     // S-mode CSRs the M-only default engine does not implement (L3/L4).
312	 312     write_csr_tolerant_gated(kCsrMepc,   state.mepc,   baseline_.mepc);
313	 313     write_csr_tolerant_gated(kCsrMcause, state.mcause, baseline_.mcause);
314	 314     write_csr_tolerant_gated(kCsrMtval,  state.mtval,  baseline_.mtval);
315	 315     write_csr_tolerant_gated(kCsrMie,    state.mie,    baseline_.mie);
316	 316     write_csr_tolerant_gated(kCsrMip,    state.mip,    baseline_.mip);
317	 317 
318	 318     // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
319	 319     // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
320	 320     // caches) but has no cache model, so without this the cycle engine resumes
321	 321     // at the ROI with caches at their reset default -- DISABLED -- and the
322	 322     // whole measured window runs uncached, inflating it severalfold. Tolerant
323	 323     // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
324	 324     // write as a no-op, and a drained 0 (caches were off) restores the reset
325	 325     // state, so this is always safe to issue.
326	 326     if (wm_live(state, HYBRID_WM_MCACHE_CTL))
327	 327       write_csr_tolerant_gated(kCsrMcacheCtl, state.mcache_ctl,
328	 328                                baseline_.mcache_ctl);
329	 329     if (wm_live(state, HYBRID_WM_MMISC_CTL))
330	 330       write_csr_tolerant_gated(kCsrMmiscCtl,  state.mmisc_ctl,
331	 331                                baseline_.mmisc_ctl);
332	 332 
333	 333     // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
334	 334     // from QEMU1's drain value. Without this, vsim's local counter starts
335	 335     // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
336	 336     // longer measure the ROI. PB fallback uses x5 as scratch; safe to
337	 337     // overwrite here as the GPR loop already ran.
338	 338     write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
339	 339     write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
340	 340 
341	 341     clear_cmderr_if_set();
342	 342     request_resume();
343	 343     poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
344	 344                    "ResumeDriver resume");
345	 345   }
