358	 358   void write_64bit_register(uint16_t regno, uint64_t value)
359	 359   {
360	 360     write_register_abstract(bus_, regno, value);
361	 361   }
362	 362 
363	 363   // v5: write back the WRITABLE boot-static L2C config registers via
364	 364   // Program-Buffer word stores. The L2C block is MMIO, not a CSR, so each write
365	 365   // is `sw x5, 0(x6)` with the register address staged in x6 and the value (low
366	 366   // word) in x5. Restores ONLY the config registers the ROI can hold as plain
367	 367   // state: Control (CEN/prefetch/ECC/RAM timing), HPM Control, Way Allocation
368	 368   // Masks. The read-only Configuration Register, the side-effecting CCTL command
369	 369   // registers (writing one re-issues an L2 cache op), and the write-1-clear
370	 370   // error registers are captured in the record but NEVER written back.
371	 371   //
372	 372   // Hard-gated on the engine having an L2C (l2c_present_): a store to an absent
373	 373   // L2C region faults the Program Buffer, so unlike a tolerant CSR write this
374	 374   // must issue nothing on a core without an L2C. x5/x6 are safe scratch here --
375	 375   // the caller runs this before the GPR loop, which overwrites both.
376	 376   void restore_l2c(const hybrid_state_v1& state)
377	 377   {
378	 378     if (!(state.flags & HYBRID_FLAG_L2C)) return;
379	 379     if (!l2c_present_) return;
380	 380 
381	 381     pb_store_l2c_reg(HYBRID_L2C_OFF_CONTROL,
382	 382                      state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8]);
383	 383     pb_store_l2c_reg(HYBRID_L2C_OFF_HPM_CTL0,
384	 384                      state.l2c.reg[HYBRID_L2C_OFF_HPM_CTL0 / 8]);
385	 385     for (uint32_t i = 0; i < HYBRID_L2C_WAYMASK_NUM; ++i) {
386	 386       const uint32_t off = HYBRID_L2C_OFF_WAYMASK0 + i * 8u;
387	 387       pb_store_l2c_reg(off, state.l2c.reg[off / 8]);
388	 388     }
389	 389   }
390	 390 
391	 391   // One L2C register store: stage the MMIO address in x6 and the value's low
392	 392   // word in x5, then execute `sw x5, 0(x6)` in the Program Buffer. Word store
393	 393   // per DS220 11.8.3 (single transfer, access size < 8 bytes); all documented
394	 394   // L2C control bits live in the low 32.
395	 395   void pb_store_l2c_reg(uint32_t offset, uint64_t value)
396	 396   {
397	 397     write_register_abstract(bus_, regno_gpr(6), l2c_base_ + offset);
398	 398     write_register_abstract(bus_, regno_gpr(5), value & 0xffffffffu);
399	 399     const std::array<uint32_t, 1> pb = { encode_sw(5, 6, 0) };
400	 400     exec_progbuf(bus_, std::span<const uint32_t>{pb});
401	 401   }
402	 402 
403	 403   // Andes V5 + M-ext CSR restore: one caps-gated abstract write per CSR
404	 404   // (pmaaddr before pmacfg, mirroring the PMP restore ordering), each gated by
405	 405   // the LG1 reset baseline. Abstract-only by design -- a batched Program-Buffer
406	 406   // sweep can't tolerate a cmderr on one CSR without corrupting the rest of the
407	 407   // batch (a WARL/read-only CSR faults the whole group mid-sweep), whereas the
408	 408   // per-CSR abstract path tolerates a single failure and moves on.
409	 409   void restore_andes_m_ext(const hybrid_state_v1& state)
410	 410   {
411	 411     const bool andes = state.flags & HYBRID_FLAG_ANDES;
412	 412     const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
413	 413     if (!andes && !mext) return;
414	 414 
415	 415     // Each write is double-gated: caps (the ENGINE implements the CSR) and the
416	 416     // v6 write-mask (the PRODUCER's guest actually wrote it -- wm_live).
417	 417     if (andes) {
418	 418 #define X(field, addr, name)                                                  \
419	 419   if (caps_.supports_csr(addr)                                                \
420	 420       && wm_live(state, HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field))  \
421	 421     write_csr_tolerant_gated(addr, state.andes.field, baseline_.andes.field);
422	 422       HYBRID_ANDES_CSR_LIST(X)
423	 423 #undef X
424	 424       for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
425	 425         if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i)
426	 426             && wm_live(state, HYBRID_WM_PMAADDR_BASE + i))
427	 427           write_csr_tolerant_gated(HYBRID_PMA_ADDR0_CSR + i,
428	 428                                    state.andes.pmaaddr[i],
429	 429                                    baseline_.andes.pmaaddr[i]);
430	 430       for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
431	 431         if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i)
432	 432             && wm_live(state, HYBRID_WM_PMACFG_BASE + i))
433	 433           write_csr_tolerant_gated(HYBRID_PMA_CFG0_CSR + 2 * i,
434	 434                                    state.andes.pmacfg[i],
435	 435                                    baseline_.andes.pmacfg[i]);
436	 436     }
437	 437     if (mext) {
438	 438 #define X(field, addr, name)                                                  \
439	 439   if (caps_.supports_csr(addr)                                                \
440	 440       && wm_live(state, HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field))  \
441	 441     write_csr_tolerant_gated(addr, state.m_ext.field, baseline_.m_ext.field);
442	 442       HYBRID_M_EXT_CSR_LIST(X)
443	 443 #undef X
444	 444     }
445	 445   }
446	 446 
447	 447   // Abstract-first CSR write with Program Buffer fallback.
448	 448   // Tries an abstract register write; if the DM signals cmderr, clears it,
449	 449   // stages the value in scratch_gpr via abstract GPR write, then executes a
450	 450   // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
451	 451   // to x5 (t0) which the GPR restore loop overwrites later.
452	 452   void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
453	 453                                  uint8_t scratch_gpr = 5)
454	 454   {
455	 455     write_64bit_register(regno_csr(csr), value);
456	 456     if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
457	 457     bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
458	 458     write_64bit_register(regno_gpr(scratch_gpr), value);
459	 459     const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
460	 460     exec_progbuf(bus_, std::span<const uint32_t>{pb});
461	 461   }
462	 462 
463	 463   // Write a CSR-addressable register and clear any cmderr the DM raised.
464	 464   // Used for CSRs whose abstract-access support may be implementation
465	 465   // dependent; a missing CSR mirrors as a no-op rather than blocking the
466	 466   // remaining writes.
467	 467   void write_csr_tolerant(uint16_t csr, uint64_t value)
468	 468   {
469	 469     write_64bit_register(regno_csr(csr), value);
470	 470     clear_cmderr_if_set();
471	 471   }
472	 472 
473	 473   // v6: true when the handoff says this mask-governed CSR is live -- the
474	 474   // producer's guest actually wrote it, or the producer carried no mask at all
475	 475   // (pre-v6 file: restore-everything fallback). An untouched CSR is skipped so
476	 476   // the engine keeps its OWN reset value: the drained value is only the
477	 477   // producer's reset default, which may legitimately differ from this RTL's
478	 478   // (msp_bound all-ones vs 0, milmb.IEN 0 vs 1; see hybrid/write_mask.h).
479	 479   static auto wm_live(const hybrid_state_v1& state, int slot) -> bool
480	 480   {
481	 481     if (!(state.flags & HYBRID_FLAG_WRITE_MASK)) return true;
482	 482     return hybrid_wm_test(state.write_mask, static_cast<unsigned>(slot)) != 0;
483	 483   }
484	 484 
485	 485   // LG1: true (and counted) when the reset baseline marks this write a no-op.
486	 486   auto baseline_skips(uint64_t value, uint64_t reset_value) -> bool
487	 487   {
488	 488     if (!has_baseline_ || value != reset_value) return false;
489	 489     ++baseline_skip_count_;
490	 490     return true;
491	 491   }
492	 492 
493	 493   // Tolerant CSR write elided when the value already equals the engine's
494	 494   // reset value (reset_value is only meaningful when the baseline is set;
495	 495   // baseline_ is zero-initialized otherwise and baseline_skips ignores it).
496	 496   void write_csr_tolerant_gated(uint16_t csr, uint64_t value,
497	 497                                 uint64_t reset_value)
498	 498   {
499	 499     if (baseline_skips(value, reset_value)) return;
500	 500     write_csr_tolerant(csr, value);
501	 501   }
502	 502 
503	 503   // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
504	 504   // is rejected until the bits are W1C-cleared. We tolerate per-register
505	 505   // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
506	 506   // error before resuming so the hart isn't left in a stuck state.
507	 507   // B17: record the last observed non-zero cmderr and a clear count so a
508	 508   // partially-broken restore is observable via the public accessors
509	 509   // instead of silently swallowed.
510	 510   void clear_cmderr_if_set()
511	 511   {
512	 512     const auto status = bus_.read(kAbstractcs);
513	 513     const auto code = (status & kAbstractcsCmderrMask) >> 8;
514	 514     if (code != 0u) {
515	 515       last_observed_cmderr_ = code;
516	 516       ++cmderr_clear_count_;
517	 517       bus_.write(kAbstractcs, kAbstractcsCmderrMask);
518	 518     }
519	 519   }
520	 520 
521	 521   DmiBus& bus_;
522	 522   uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
523	 523   AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
524	 524   bool l2c_present_ = false;                  // v5: engine has an L2C (set_l2c)
525	 525   uint64_t l2c_base_ = 0;                     // v5: L2C MMIO register base
526	 526   hybrid_state_v1 baseline_{};                // LG1: engine reset-state drain
527	 527   bool has_baseline_ = false;                 // baseline_ valid only when set
528	 528   bool v_cfg_at_reset_ = true;                // false: capture clobbered vcfg
529	 529   uint64_t baseline_skip_count_ = 0;          // LG1: elided tolerant writes
530	 530   uint32_t last_observed_cmderr_ = 0;
531	 531   uint64_t cmderr_clear_count_   = 0;
532	 532 
533	 533 public:
534	 534   // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
535	 535   // at least one abstract write tripped a sticky cmderr the restore
536	 536   // tolerated by clearing. cmderr_clear_count() is the total number of
537	 537   // such clears across all calls into clear_cmderr_if_set() this run.
538	 538   auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
539	 539   auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
540	 540 };
