542	 542 // Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
543	 543 // via an Abstract Command. Halts-and-reads contract: caller must have the
544	 544 // hart in the halted state. Shared by StateDrain (drain at exit). If
545	 545 // abstractcs.cmderr goes sticky after the command, the helper clears it and
546	 546 // reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
547	 547 // instead of corrupting the adjacent field.
548	 548 inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
549	 549                                      const char* poll_label
550	 550                                        = "read_register_64")
551	 551   -> std::optional<uint64_t>
552	 552 {
553	 553   using RD = ResumeDriver;
554	 554   bus.write(RD::kCommand,
555	 555             access_register_command(regno, AarSize::Bits64, /*write=*/false));
556	 556   poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
557	 557   const auto status = bus.read(RD::kAbstractcs);
558	 558   if ((status & RD::kAbstractcsCmderrMask) != 0u) {
559	 559     bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
560	 560     return std::nullopt;
561	 561   }
562	 562   const uint64_t lo = bus.read(RD::kData0);
563	 563   const uint64_t hi = bus.read(RD::kData1);
564	 564   return lo | (hi << 32);
565	 565 }
566	 566 
567	 567 inline auto read_register_64(DmiBus& bus, uint16_t regno,
568	 568                              const char* poll_label = "read_register_64")
569	 569   -> uint64_t
570	 570 {
571	 571   return read_register_64_checked(bus, regno, poll_label).value_or(0u);
572	 572 }
