   1 // ResumeDriver translates a hybrid_state_v1 into a sequence of DMI register
   2 // ops against the RISC-V Debug Module. The orchestration is testable in
   3 // isolation by injecting a recording bus.
   4 //
   5 // GPR transport complete: the driver restores GPRs x1..x31 and DPC. These
   6 // cases pin the halt/resume handshake, the x1..x31 program (one COMMAND per
   7 // register, x0 skipped), the DPC write, that M-mode CSRs/PMP are NOT programmed
   8 // via DM abstract at this stage, and the header guard.
   9 //
  10 // FP restore, complete: under HYBRID_FLAG_FP the driver first writes mstatus
  11 // (force FS = Initial so the abstract FPR writes are accepted even when the
  12 // drained field is Off), then programs f0..f31 via abstract commands and
  13 // restores fcsr (frm + sticky fflags, L20) under the same FS gate. With FP
  14 // clear the driver issues no FPR or fcsr write. B17 pins the cmderr
  15 // diagnostic side channel; B9 pins that every abstract write busy-polls
  16 // abstractcs before the next caller inspects cmderr.
  17 
  18 #include "hybrid/abstract_command.hpp"
  19 #include "hybrid/resume_driver.hpp"
  20 #include "hybrid/state_abi.h"
  21 
  22 #define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
  23 #include <doctest.h>
  24 
  25 #include <cstdint>
  26 #include <optional>
  27 #include <vector>
  28 
  29 namespace {
  30 
  31 // DMI register addresses from RISC-V Debug Spec 1.0.
  32 constexpr uint8_t kDmcontrol  = 0x10;
  33 constexpr uint8_t kDmstatus   = 0x11;
  34 constexpr uint8_t kAbstractcs = 0x16;
  35 constexpr uint8_t kCommand    = 0x17;
  36 constexpr uint8_t kData0      = 0x04;
  37 constexpr uint8_t kData1      = 0x05;
  38 
  39 // CSR numbers from Debug Spec.
  40 constexpr uint16_t kCsrDpc = 0x7B1;
  41 
  42 struct DmiOp
  43 {
  44   enum class Kind
  45   {
  46     Write,
  47     Read,
  48   };
  49   Kind kind;
  50   uint8_t reg;
  51   uint32_t value;  // for writes only
  52 };
  53 
  54 struct RecordingBus final : hybrid::DmiBus
  55 {
  56   std::vector<DmiOp> ops;
  57 
  58   // bit 9: allhalted, bit 17: allresumeack. Answering both lets the poll
  59   // loops finish on their first read. abstractcs reads return 0 (busy clear,
  60   // no cmderr), so each abstract write completes immediately.
  61   uint32_t dmstatus_value = 0;
  62 
  63   // When set, an abstract write-COMMAND to this CSR regno raises a sticky
  64   // cmderr (cleared only by the W1C abstractcs write the driver issues).
  65   // Models a hart that NACKs a particular abstract CSR access.
  66   std::optional<uint16_t> fail_csr_write;
  67 
  68   void write(uint8_t reg, uint32_t value) override
  69   {
  70     ops.push_back({DmiOp::Kind::Write, reg, value});
  71     if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
  72       cmderr_sticky_ = false;  // W1C clear
  73     if (reg == kCommand && fail_csr_write) {
  74       const auto regno    = static_cast<uint16_t>(value & 0xffffu);
  75       const bool is_write = ((value >> 16) & 1u) != 0u;
  76       if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
  77         cmderr_sticky_ = true;
  78     }
  79   }
  80 
  81   auto read(uint8_t reg) -> uint32_t override
  82   {
  83     ops.push_back({DmiOp::Kind::Read, reg, 0});
  84     if (reg == kDmstatus) return dmstatus_value;
  85     if (reg == kAbstractcs && cmderr_sticky_) return kCmderrMask;
  86     return 0;
  87   }
  88 
  89 private:
  90   static constexpr uint32_t kCmderrMask = 0x7u << 8;
  91   bool cmderr_sticky_ = false;
  92 };
  93 
  94 auto rv64_state(uint64_t pc, uint64_t x1) -> hybrid_state_v1
  95 {
  96   hybrid_state_v1 s{};
  97   s.magic = HYBRID_STATE_MAGIC;
  98   s.version = HYBRID_STATE_VERSION;
  99   s.flags = HYBRID_FLAG_RV64;
 100   s.pc = pc;
 101   s.priv = 3;
 102   s.gpr[1] = x1;
 103   return s;
 104 }
 105 
 106 auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
 107   -> std::vector<uint32_t>
 108 {
 109   std::vector<uint32_t> values;
 110   for (const auto& op : ops)
 111     if (op.kind == DmiOp::Kind::Write && op.reg == reg)
 112       values.push_back(op.value);
 113   return values;
 114 }
